import configparser
import difflib

# Define the hardened baseline configuration
baseline_config = """
http {
    ...
    server_tokens off;
    server_signature off;
    expose-index off;
    ...
}

server {
    ...
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers on;
    ssl_dhparam /path/to/dhparams.pem;
    ...
}
"""

# Define the path to your Nginx configuration file
config_file_path = '/etc/nginx/nginx.conf'

# Parse the baseline configuration into a ConfigParser object
baseline_config_parser = configparser.ConfigParser()
baseline_config_parser.read_string(baseline_config)

# Parse your actual Nginx configuration file into a ConfigParser object
config_parser = configparser.ConfigParser()
with open(config_file_path, 'r') as f:
    config_parser.read_file(f)

# Compare the two configurations and print out any differences
differences = difflib.unified_diff(
    config_parser.items('http'),
    baseline_config_parser.items('http'),
    fromfile='your-config',
    tofile='baseline'
)
